#include "native/providers/gdn/sm121_mtp_kv_math.h"
#include <array>
#include <filesystem>
#include <fstream>
#include <iostream>
#include <stdexcept>
#include <string>
#include <vector>

namespace q1 = qrt_sm121_q1;
namespace fma = qrt_sm121_bf16_fma;

template<class T> std::vector<T> read(const char* path, size_t count) {
    std::ifstream file(path, std::ios::binary | std::ios::ate);
    if (!file || file.tellg() != std::streamoff(count * sizeof(T)))
        throw std::runtime_error("input extent");
    std::vector<T> values(count);
    file.seekg(0);
    file.read(reinterpret_cast<char*>(values.data()), count * sizeof(T));
    if (!file) throw std::runtime_error("input read");
    return values;
}

int main(int argc, char** argv) try {
    if (argc != 6) throw std::runtime_error("norm coefficients heads position output-prefix");
    const unsigned heads = std::stoul(argv[3]), position = std::stoul(argv[4]);
    if ((heads != 2u && heads != 16u) || position >= 264736u)
        throw std::runtime_error("shape");
    const auto norm = read<uint16_t>(argv[1], size_t(heads) * 256u);
    std::ifstream cache(argv[2], std::ios::binary | std::ios::ate);
    if (!cache || cache.tellg() != std::streamoff(264736u * 64u * sizeof(uint16_t)))
        throw std::runtime_error("coefficient extent");
    std::array<uint16_t, 64> coefficients;
    cache.seekg(size_t(position) * 64u * sizeof(uint16_t));
    cache.read(reinterpret_cast<char*>(coefficients.data()), sizeof(coefficients));
    if (!cache) throw std::runtime_error("coefficient read");
    for (unsigned mode = 0; mode < 3u; ++mode) {
        const std::string path = std::string(argv[5]) + ".mode" + std::to_string(mode) + ".bf16.bin";
        if (std::filesystem::exists(path)) throw std::runtime_error("output exists");
        auto output = norm;
        for (unsigned head = 0; head < heads; ++head) {
            const uint16_t* input = norm.data() + size_t(head) * 256u;
            for (unsigned channel = 0; channel < 256u; ++channel) {
                uint16_t result = input[channel];
                if (mode == 2u) {
                    result = qrt_sm121_mtp::key_rotated(input, channel, coefficients.data());
                } else if (channel < 64u) {
                    const unsigned pair = channel & 31u;
                    const uint16_t sine_product = q1::bf16(q1::multiply(
                        q1::widen(input[channel < 32u ? pair + 32u : pair]),
                        q1::widen(coefficients[32u + pair])));
                    const float addend = q1::widen(uint16_t(sine_product ^ (channel < 32u ? 0x8000u : 0u)));
                    result = q1::bf16(mode == 1u
                        ? fma::rounded(q1::widen(input[channel]), q1::widen(coefficients[pair]), addend)
                        : fmaf(q1::widen(input[channel]), q1::widen(coefficients[pair]), addend));
                }
                output[size_t(head) * 256u + channel] = result;
            }
        }
        std::ofstream file(path, std::ios::binary);
        file.write(reinterpret_cast<const char*>(output.data()), output.size() * sizeof(uint16_t));
        file.close();
        if (!file) throw std::runtime_error("output write");
    }
    std::cout << "{\"heads\":" << heads << ",\"position\":" << position
              << ",\"elements_per_mode\":" << norm.size() << ",\"modes\":3}\n";
    return 0;
} catch (const std::exception& error) {
    std::cerr << error.what() << '\n';
    return 2;
}

